input, button { font:inherit; padding:12px; border-radius:8px; border:1px solid #30363d; background:#161b22; color:var(--fg); }
button { cursor:pointer; background:var(--acc); border-color:var(--acc); color:#fff; }
#msg { min-height:1.2em; margin:0; color:#ff7b72; }
#stage { position:fixed; inset:0; background:#000; }
#screen { position:absolute; outline:none; cursor:default; touch-action:none; }
#bar { position:fixed; top:0; left:50%; transform:translate(-50%,-100%); display:flex; gap:8px; align-items:center;
  padding:8px 12px; background:rgba(22,27,34,.95); border-radius:0 0 10px 10px; transition:transform .2s; z-index:5; }
#bar:hover, #bar.show { transform:translate(-50%,0); }
#bar button { padding:6px 10px; font-size:13px; background:#21262d; border-color:#30363d; }
#status { color:var(--mut); font-size:13px; margin-right:6px; }

#hint { display:none; color:#8b949e; font-size:13px; }
#bar.menu #hint { display:inline; }
#bar.menu #hint b { color:#e6edf3; }
